import {assessDelivery} from "../../lib/delivery-assessment.ts";
import {prepareProjectEvaluation,projectQuote,validateProjectCorpus} from "../../scripts/run-project-assessment-evaluation.ts";
import {evidenceReplayImplementationSnapshot} from "../../scripts/replay-evidence-actions-2026-11-06.mjs";
const ROOT=fileURLToPath(new URL("../../",import.meta.url)),OUT=path.dirname(fileURLToPath(import.meta.url));
const hash=b=>createHash("sha256").update(b).digest("hex"),paths={live:path.join(OUT,"cycle-18-eight-first-live-admitted.json"),corpus:path.join(ROOT,"scripts/evidence-actions-boundary-corpus-2026-11-06.json"),refs:path.join(ROOT,"scripts/evidence-actions-boundary-references-2026-11-06.json")},inputs={};
for(const[k,file]of Object.entries(paths)){const bytes=await readFile(file);inputs[k]={file,sha256:hash(bytes),value:JSON.parse(bytes)};}
assert.equal(inputs.corpus.sha256,"b0ed37335770f9de649974cd55ca410911a77e0e9199d2e94501a774ca4f62a3");assert.equal(inputs.refs.sha256,"98def261ee50f56ff97f6ccdfb88b7e74e8ba9b126cc4f0c4f3f4baf8f803c51");
const live=inputs.live.value,corpus=validateProjectCorpus(inputs.corpus.value),rows=[],closure=await evidenceReplayImplementationSnapshot();
const priorFetch=globalThis.fetch;let externalAttempts=0,intercepted=0;globalThis.fetch=async()=>{externalAttempts++;throw new Error("No network allowed in original-body replay.");};
let preparation;
try{
 preparation=await prepareProjectEvaluation(corpus,{corpusText:(await readFile(paths.corpus)).toString("utf8"),env:{DEEPSEEK_MODEL:live.model}});
 for(const project of corpus.projects){
  const previous=live.results.find(r=>r.id===project.id),frozen=live.snapshot.projects.find(p=>p.id===project.id),prepared=preparation.prepared.find(p=>p.project.id===project.id),old=previous.application.report;
  assert.equal(prepared.body,frozen.requestBody);assert.equal(hash(prepared.body),frozen.plan.requestSha256);
  const quote=projectQuote(project),before=structuredClone(quote),OriginalDate=globalThis.Date,originalUUID=crypto.randomUUID;
  globalThis.Date=new Proxy(OriginalDate,{construct(target,args,newTarget){return args.length?Reflect.construct(target,args,newTarget):new target(old.assessedAt);}});crypto.randomUUID=()=>old.id;
  let report,calls=0;
  try{report=await assessDelivery(quote,{DEEPSEEK_API_KEY:"offline-original-body-replay",DEEPSEEK_MODEL:live.model},async(url,init)=>{
   calls++;intercepted++;assert.equal(calls,1);assert.equal(String(url),"https://api.deepseek.com/beta/chat/completions");assert.equal(String(init.body),frozen.requestBody);
   return new Response(previous.raw.bodyText,{status:previous.raw.httpStatus,headers:{"Content-Type":"application/json"}});
  });}finally{globalThis.Date=OriginalDate;crypto.randomUUID=originalUUID;}
  assert.equal(calls,1);assert.deepEqual(quote,before);
  const alias=project.id==="evidence-actions-wrong-page-role-alias";
  if(!alias)assert.deepEqual(report,old,"A non-alias original report changed.");
  else{
   assert.equal(old.items[0].status,"changes_suggested");assert.equal(old.risks.length,1);assert.equal(report.items[0].status,"insufficient_evidence");
   assert.deepEqual(report.items[0].evidenceNeed,{schema:"source-evidence-need-v1",reason:"page_scope",targetFiles:[]});
   assert.match(report.items[0].explanation,/scope|map|confirm|role/iu);
   const expected=structuredClone(old);expected.items[0]={...expected.items[0],status:"insufficient_evidence",explanation:report.items[0].explanation,evidenceNeed:report.items[0].evidenceNeed};
   expected.risks=[];expected.withheldRisks={version:1,reason:"item_status_adjusted",adjustedCriteria:[{criterionId:"coverage-1",originalStatus:"changes_suggested",publishedStatus:"insufficient_evidence"}],entries:old.risks.map((risk,originalRiskIndex)=>({originalRiskIndex,risk}))};
   expected.limitations.splice(2,0,"1 item status(es) were adjusted by system checks. 1 unreviewed optional AI risk(s) are temporarily withheld; use item-level evidence. This publication gate does not accept work, authorize or trigger payment.");
   assert.deepEqual(report,expected,"Alias repair changed fields outside the explicit status/explanation/need/risk-disposition/system-note scope.");
  }
  for(const kind of["items","risks"])for(const row of report[kind])for(const c of row.citations)assert.equal(project.files[c.file].slice(c.start,c.end),c.excerpt);
  for(const entry of report.withheldRisks.entries)for(const c of entry.risk.citations)assert.equal(project.files[c.file].slice(c.start,c.end),c.excerpt);
  rows.push({id:project.id,requestSha256:frozen.plan.requestSha256,providerBodySha256:hash(previous.raw.bodyText),requestBytesUnchanged:true,quoteAndAcceptanceAndPaymentUnchanged:true,referenceStatus:project.criteria[0].reference.expectedStatus,
   originalStatus:old.items[0].status,currentStatus:report.items[0].status,nonAliasReportUnchanged:!alias,originalApplication:previous.application,currentApplication:{accepted:true,report,error:null}});
 }
}finally{globalThis.fetch=priorFetch;}
assert.equal(externalAttempts,0);assert.equal(rows.filter(r=>r.originalStatus!==r.currentStatus).length,1);
for(const input of Object.values(inputs))assert.equal(hash(await readFile(input.file)),input.sha256);
for(const file of closure)assert.equal(hash(await readFile(path.join(ROOT,file.file))),file.sha256);
const sourceRows=[];for(const file of closure){const bytes=await readFile(path.join(ROOT,file.file));sourceRows.push({...file,contents:bytes.toString("utf8")});}
const report={schema:"pbp-negative-scope-original-eight-body-replay-v1",mode:"controlled_application_replay",apiCalls:0,modelCalls:0,networkCalls:0,interceptedRequests:intercepted,externalAttempts,projects:8,criteria:8,unchangedNonAliasReports:7,
 originalStatusAgreement:6,currentStatusAgreement:rows.filter(r=>r.currentStatus===r.referenceStatus).length,referenceTotal:8,inputs:Object.fromEntries(Object.entries(inputs).map(([k,v])=>[k,{file:v.file,sha256:v.sha256}])),
 runtimeIdentity:"frozen_original_report_uuid_and_clock",harness:{file:path.basename(fileURLToPath(import.meta.url)),sha256:hash(await readFile(fileURLToPath(import.meta.url)))},runtimeImplementation:preparation.snapshot.implementation,rows,
 limits:["Original first-live raw answers and references remain unchanged; current application replay is not a new model inference.","Only alias changes to unknown; the missing-explicit-file policy disagreement remains in the unchanged original report.","Static citations, report inspection and evidence requests do not establish browser execution, final acceptance or payment."]};
const output=path.join(OUT,"negative-scope-eight-original-body-replay.json");await writeFile(output,JSON.stringify(report,null,2)+"\n",{flag:"wx",mode:0o600});
const providerFiles=new Set(preparation.snapshot.implementation.map(r=>r.file));
const archive={schema:"pbp-evaluated-implementation-inert-archive-v1",source:"exact-current-utf8-bytes-verified-after-original-body-replay",replayFile:path.basename(output),replaySha256:hash(await readFile(output)),providerClosureFiles:providerFiles.size,allArchivedFiles:sourceRows.length,files:sourceRows.map(r=>({...r,providerClosure:providerFiles.has(r.file)})),additionalReplayHarness:{file:report.harness.file,sha256:report.harness.sha256,contents:await readFile(fileURLToPath(import.meta.url),"utf8")},limits:["Source is inert JSON; final provider plus tracked tool closure is complete. The separate original-eight replay harness is also retained as inert text."]};
const archiveFile=path.join(OUT,"negative-scope-final-implementation.json");await writeFile(archiveFile,JSON.stringify(archive,null,2)+"\n",{flag:"wx",mode:0o600});
console.log(JSON.stringify({output,archiveFile,projects:8,unchangedNonAliasReports:7,aliasChanges:1,statusAgreement:report.currentStatusAgreement,referenceTotal:8,providerFiles:providerFiles.size,allFiles:sourceRows.length,apiCalls:0,networkCalls:0}));

// A diagnostic of an intentional conservative delta; not the strict unchanged
// regression gate, which correctly stopped on Tavola coverage-3.
import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {readFile,writeFile} from "node:fs/promises";
import path from "node:path";
import {fileURLToPath} from "node:url";
import {assessDelivery} from "../../lib/delivery-assessment.ts";
import {projectQuote,prepareProjectEvaluation,validateProjectCorpus} from "../../scripts/run-project-assessment-evaluation.ts";
const ROOT=fileURLToPath(new URL("../../",import.meta.url)),OUT=path.dirname(fileURLToPath(import.meta.url));
const hash=b=>createHash("sha256").update(b).digest("hex"),load=async file=>{const bytes=await readFile(file);return{file,sha256:hash(bytes),value:JSON.parse(bytes)};};
const prior=await load(path.join(OUT,"cycle-18-final-replay.json")),manifest=await load(path.join(OUT,"retained-replay-inputs.json"));
const archive=await load(path.join(OUT,"negative-scope-final-implementation.json"));for(const f of archive.value.files)assert.equal(hash(await readFile(path.join(ROOT,f.file))),f.sha256);
const rows=[],inputFiles=[prior,manifest,archive];let requests=0,external=0,referenceAgreements=0;
const originalFetch=globalThis.fetch;globalThis.fetch=async()=>{external++;throw new Error("No external requests allowed.");};
try{
 for(const group of manifest.value.groups){
  const c=await load(group.corpus),liveInput=await load(group.live),frozenInput=await load(group.freeze);inputFiles.push(c,liveInput,frozenInput);
  const corpus=validateProjectCorpus(c.value),live=liveInput.value,prepared=await prepareProjectEvaluation(corpus,{corpusText:(await readFile(group.corpus)).toString("utf8"),env:{DEEPSEEK_MODEL:live.model}});
  for(const project of corpus.projects){
   const old=prior.value.rows.find(r=>r.id===project.id).currentApplication.report,source=live.snapshot.projects.find(p=>p.id===project.id),retained=live.results.find(r=>r.id===project.id),p=prepared.prepared.find(p=>p.project.id===project.id);
   assert.equal(p.body,source.requestBody);const q=projectQuote(project),before=structuredClone(q),OriginalDate=globalThis.Date,uuid=crypto.randomUUID;
   globalThis.Date=new Proxy(OriginalDate,{construct(target,args,newTarget){return args.length?Reflect.construct(target,args,newTarget):new target(old.assessedAt);}});crypto.randomUUID=()=>old.id;
   let report,calls=0;try{report=await assessDelivery(q,{DEEPSEEK_API_KEY:"offline-retained-diagnostic",DEEPSEEK_MODEL:live.model},async(_url,init)=>{calls++;requests++;assert.equal(calls,1);assert.equal(String(init.body),source.requestBody);return new Response(retained.raw.bodyText,{status:retained.raw.httpStatus,headers:{"Content-Type":"application/json"}});});}finally{globalThis.Date=OriginalDate;crypto.randomUUID=uuid;}
   assert.equal(calls,1);assert.deepEqual(q,before);
   const changes=report.items.filter((item,i)=>item.status!==old.items[i].status).map(item=>({criterionId:item.criterionId,previousStatus:old.items.find(o=>o.criterionId===item.criterionId).status,currentStatus:item.status}));
   if(project.id!=="citation-relations-holdout-tavola")assert.deepEqual(report,old);
   else{
    assert.deepEqual(changes,[{criterionId:"coverage-3",previousStatus:"changes_suggested",currentStatus:"insufficient_evidence"}]);
    const item=report.items.find(i=>i.criterionId==="coverage-3"),expected=structuredClone(old);assert.deepEqual(item.evidenceNeed,{schema:"source-evidence-need-v1",reason:"page_scope",targetFiles:[]});
    expected.items[2]={...expected.items[2],status:"insufficient_evidence",explanation:item.explanation,evidenceNeed:item.evidenceNeed};
    expected.withheldRisks.adjustedCriteria.push({criterionId:"coverage-3",originalStatus:"changes_suggested",publishedStatus:"insufficient_evidence"});
    expected.limitations[2]=expected.limitations[2].replace("2 item status(es)","3 item status(es)");assert.deepEqual(report,expected);
   }
   const criterionRefs=project.criteria.map((criterion,i)=>({criterionId:criterion.id,referenceStatus:criterion.reference.expectedStatus,status:report.items[i].status}));referenceAgreements+=criterionRefs.filter(r=>r.status===r.referenceStatus).length;
   for(const row of [...report.items,...report.risks,...report.withheldRisks.entries.map(e=>e.risk)])for(const citation of row.citations)assert.equal(project.files[citation.file].slice(citation.start,citation.end),citation.excerpt);
   rows.push({id:project.id,requestSha256:source.plan.requestSha256,providerBodySha256:hash(retained.raw.bodyText),quoteAndAcceptanceAndPaymentUnchanged:true,statusChanges:changes,completeReportUnchanged:changes.length===0,criterionRefs,originalApplication:{accepted:true,report:old,error:null},currentApplication:{accepted:true,report,error:null}});
  }
 }
}finally{globalThis.fetch=originalFetch;}
assert.equal(external,0);assert.equal(rows.length,15);assert.equal(rows.flatMap(r=>r.statusChanges).length,1);
for(const input of inputFiles)assert.equal(hash(await readFile(input.file)),input.sha256);for(const f of archive.value.files)assert.equal(hash(await readFile(path.join(ROOT,f.file))),f.sha256);
const report={schema:"pbp-negative-scope-retained15-delta-diagnostic-v1",apiCalls:0,modelCalls:0,networkCalls:0,interceptedRequests:requests,projects:15,criteria:82,strictUnchangedRegressionPassed:false,strictGateOutcome:"correctly_failed_on_one_conservative_status_change",unchangedReports:14,changedReports:1,statusChanges:1,previousReferenceAgreement:79,currentReferenceAgreement:referenceAgreements,referenceTotal:82,firstRawRepliesAndReferencesUnchanged:true,inputs:inputFiles.map(({file,sha256})=>({file,sha256})),runtimeArchiveFile:path.basename(archive.file),runtimeArchiveSha256:archive.sha256,rows,
 limits:["This diagnostic is not a passing result of the strict unchanged replay. That tool correctly stopped on Tavola coverage-3.","The new unconfirmed-role guard conservatively changes one old unsupported change suggestion to unknown. The old frozen oracle remains changes_suggested, so numeric agreement decreases; no reference was edited.","Other 14 complete reports, all source citations, active/withheld risk contents, request bytes, acceptance and payment state are unchanged. In Tavola only coverage-3 need/explanation/status, its from/to ledger entry and adjustment-count note differ.","No new model inference, provider or browser call occurred. Original first attempts remain retained."]};
const output=path.join(OUT,"negative-scope-retained15-delta-diagnostic.json");await writeFile(output,JSON.stringify(report,null,2)+"\n",{flag:"wx",mode:0o600});console.log(JSON.stringify({output,strictUnchangedRegressionPassed:false,unchangedReports:14,changedReports:1,statusChanges:1,previousReferenceAgreement:79,currentReferenceAgreement:referenceAgreements,referenceTotal:82,apiCalls:0,networkCalls:0}));
